#include "scheduler.h"

#include <assert.h>
#include <stdio.h>

static void test_bulk_submit_rejects_whole_batch_when_cumulative_exceeds_capacity(void) {
    Scheduler s;
    scheduler_init(&s);
    scheduler_set_max_concurrent(&s, 2);

    int priorities[3] = {1, 1, 1};
    const char *payloads[3] = {"a", "b", "c"};
    int out_ids[3];
    int result = scheduler_bulk_submit_and_run_now(&s, 3, priorities, payloads, out_ids);
    assert(result == 0);
    assert(s.running_count == 0);
}

static void test_bulk_submit_succeeds_within_capacity(void) {
    Scheduler s;
    scheduler_init(&s);
    scheduler_set_max_concurrent(&s, 3);

    int priorities[2] = {1, 1};
    const char *payloads[2] = {"a", "b"};
    int out_ids[2];
    int result = scheduler_bulk_submit_and_run_now(&s, 2, priorities, payloads, out_ids);
    assert(result == 1);
    assert(s.running_count == 2);
}

int main(void) {
    test_bulk_submit_rejects_whole_batch_when_cumulative_exceeds_capacity();
    test_bulk_submit_succeeds_within_capacity();
    printf("PASS\n");
    return 0;
}

